pub fn participle(word: &str, participle: Participle) -> Option<String> {
    Latin::new().participle(word, participle)
}

/// Every candidate for [`participle`], most likely first. Confidences sum to the
/// probability that the word has such a form at all.
pub fn participle_scored(word: &str, participle: Participle) -> Vec<Candidate> {
    Latin::new().participle_scored(word, participle)
}

/// The gerund (genitive, dative, accusative, ablative).
///
/// `word` may be a citation: the lemma, then any of `infinitive.act.pres`, `verb.ind.act.perf.1.sg`, `supine.acc` separated by commas.
/// Given parts are output exactly; the rest is predicted to agree with them.
pub fn gerund(word: &str, case: Case) -> Option<String> {
    Latin::new().gerund(word, case)
}

/// Every candidate for [`gerund`], most likely first. Confidences sum to the
/// probability that the word has such a form at all.
pub fn gerund_scored(word: &str, case: Case) -> Vec<Candidate> {
    Latin::new().gerund_scored(word, case)
}

/// The supine (accusative and ablative).
///
/// `word` may be a citation: the lemma, then any of `infinitive.act.pres`, `verb.ind.act.perf.1.sg`, `supine.acc` separated by commas.
/// Given parts are output exactly; the rest is predicted to agree with them.
pub fn supine(word: &str, case: Case) -> Option<String> {
    Latin::new().supine(word, case)
}

/// Every candidate for [`supine`], most likely first. Confidences sum to the
/// probability that the word has such a form at all.
pub fn supine_scored(word: &str, case: Case) -> Vec<Candidate> {
    Latin::new().supine_scored(word, case)
}

/// A declined pronoun or determiner.
pub fn pronoun(word: &str, case: Case, gender: Gender, number: Number) -> String {
    Latin::new().pronoun(word, case, gender, number)
}

/// Every candidate for [`pronoun`], most likely first; confidences sum to 1.
pub fn pronoun_scored(word: &str, case: Case, gender: Gender, number: Number) -> Vec<Candidate> {
    Latin::new().pronoun_scored(word, case, gender, number)
}

/// A declined numeral.
pub fn numeral(word: &str, case: Case, gender: Gender, number: Number) -> String {
    Latin::new().numeral(word, case, gender, number)
}

/// Every candidate for [`numeral`], most likely first; confidences sum to 1.
pub fn numeral_scored(word: &str, case: Case, gender: Gender, number: Number) -> Vec<Candidate> {
    Latin::new().numeral_scored(word, case, gender, number)
}

/// The gender of a noun lemma (or citation), with confidence, most likely
/// first. Predicted from the word's shape when it isn't attested.
pub fn gender(word: &str) -> Vec<(Gender, f32)> {
    inherent(0, 0, word, &Gender::ALL)
}

/// Per part of speech: the cells a citation's extra parts fill, and the
/// markers of its inherent features (`m`, `anim`, …).
struct Part {
    citation: &'static [usize],
    markers: &'static [&'static [&'static str]],
}

const PARTS: [Part; 5] = [
    Part {
        citation: &[2],
        markers: &[&["m", "f", "n"]],
    }, // noun
    Part {
        citation: &[2, 4],
        markers: &[],
    }, // adjective
    Part {
        citation: &[168, 18, 187],
        markers: &[],
    }, // verb
    Part {
        citation: &[],
        markers: &[],
    }, // pronoun
    Part {
        citation: &[],
        markers: &[],
    }, // numeral
];

fn citation<'s>(p: &flexion::Pos<'_, 'static>, pos: usize, word: &'s str) -> flexion::Citation<'s> {
    match PARTS.get(pos) {
        Some(part) => p.citation_marked(word, part.citation, part.markers),
        None => p.citation(word, &[]),
    }
}

fn quick(pos: usize, word: &str, cell: usize, options: Options) -> String {
    match model().and_then(|m| m.pos(pos)) {
        Some(p) => p.best(&citation(&p, pos, word), cell, options),
        None => word.to_string(),
    }
}

fn scored(pos: usize, word: &str, cell: usize, options: Options) -> Vec<Candidate> {
    match model().and_then(|m| m.pos(pos)) {
        Some(p) => p.candidates(&citation(&p, pos, word), cell, options),
        None => vec![Candidate {
            form: word.to_string(),
            confidence: 0.0,
        }],
    }
}

fn optional(pos: usize, word: &str, cell: usize, options: Options) -> Option<String> {
    let p = model()?.pos(pos)?;
    let c = citation(&p, pos, word);
    (p.has_cell(&c, cell) >= 0.5).then(|| p.best(&c, cell, options))
}

fn optional_scored(pos: usize, word: &str, cell: usize, options: Options) -> Vec<Candidate> {
    let Some(p) = model().and_then(|m| m.pos(pos)) else {
        return Vec::new();
    };
    let c = citation(&p, pos, word);
    let exists = p.has_cell(&c, cell);
    let mut out = p.candidates(&c, cell, options);
    for x in &mut out {
        x.confidence *= exists;
    }
    out
}

fn inherent<T: Copy>(pos: usize, feature: usize, word: &str, values: &[T]) -> Vec<(T, f32)> {
    let Some(p) = model().and_then(|m| m.pos(pos)) else {
        return Vec::new();
    };
    let c = citation(&p, pos, word);
    p.inherent(&c, feature)
        .into_iter()
        .filter_map(|(v, q)| values.get(usize::from(v)).map(|&t| (t, q)))
        .collect()
}
